{
  "initial_state": "evening_arrival",
  "states": [
    {
      "id": "evening_arrival",
      "description": "The person arrives home, adjusts the climate, and gets a drink.",
      "rules": [
        {
          "trigger": "air conditioner off, indoor temperature 29 degrees Celsius",
          "action": "turn on the air conditioner and set temperature to 26 degrees Celsius"
        },
        {
          "trigger": "The person enters through the front door",
          "action": "take a cola out of the refrigerator, place it on the side table, and close the refrigerator door"
        },
        {
          "trigger": "refrigerator door has been open for 1 minute",
          "action": "close the refrigerator door"
        }
      ],
      "next": [
        {
          "to": "laundry_handling",
          "on": "washing machine cycle finished"
        }
      ]
    },
    {
      "id": "laundry_handling",
      "description": "The person transfers laundry from the washing machine to the dryer.",
      "rules": [
        {
          "trigger": "washing machine cycle finished",
          "action": "take the laundry out of the washing machine, put it into the dryer, close the dryer door, and start the dryer"
        }
      ],
      "next": [
        {
          "to": "kitchen_cleanup",
          "on": "refrigerator door opened"
        }
      ]
    },
    {
      "id": "kitchen_cleanup",
      "description": "The person drinks milk and cleans up the used cup.",
      "rules": [
        {
          "trigger": "empty cup on the kitchen counter",
          "action": "put the empty cup into the dishwasher and close the dishwasher door"
        }
      ],
      "next": []
    }
  ]
}
